package tui

import "github.com/Grenco/omarchy-blueprint/internal/tui/components"

type ScreenSection string

const (
	SectionWorkflow      ScreenSection = "Workflow"
	SectionSoftware      ScreenSection = "Software"
	SectionCustomisation ScreenSection = "Customisation"
	SectionProfile       ScreenSection = "Profile"
)

type ScreenInfo struct {
	ID       ScreenID
	Label    string
	Section  ScreenSection
	Short    string
	Long     string
	Keywords string
}

var screenCatalog = []ScreenInfo{
	{ScreenOverview, "Overview", "", "See what Blueprint has saved, what differs on this computer, and what needs attention.", "What is this page for?\nOverview is the starting point. It shows what Blueprint has saved, what is different on this computer, and anything that needs your attention.\n\nWhat can I do here?\nItems are grouped as Needs attention (something is blocked or unresolved), Changes available (differences Capture or Restore could act on), and Intentional differences (settings your Capture and Restore choices deliberately leave alone on this computer). Open an item to go to the page where you can review or act on it.\n\nWill this change my computer or only my saved profile?\nNeither. Overview only reads your saved profile and this computer.", "home summary attention warning difference drift"},
	{ScreenCapture, "Capture", SectionWorkflow, "Save selected changes from this computer into your Blueprint profile.", "What is this page for?\nCapture saves selected settings from this computer into your Blueprint profile. Use it after you change your setup on purpose and want Blueprint to remember it.\n\nWhat can I do here?\nChoose categories, then review what would be saved. Settings are grouped as Changes, Preserved by policy (settings you have chosen not to save) and Blocked (settings Blueprint's safety checks won't save, with the reason). Before approving, you can switch individual settings between Include and Preserve. New Services start unselected: Space chooses one for this review, and v shows advanced candidates.\n\nWill this change my computer or only my saved profile?\nOnly your saved profile. Capture reads this computer and never changes it. Blueprint re-checks this computer and your choices just before it saves anything. Capture does not send changes to your other computers; Sync or Profile Git does that.", "save remember update profile"},
	{ScreenRestore, "Restore", SectionWorkflow, "Apply selected saved settings to this computer, after reviewing the changes.", "What is this page for?\nRestore applies selected saved settings to this computer, after you review the changes.\n\nWhat can I do here?\nReview the plan, then Apply it. Two run settings control how far Restore goes, and only for this run: Conflict handling — Safe leaves a setting alone when this computer has a conflicting change, while Force replaces it with the saved version. Convergence — Additive only adds or updates saved settings, while Exact can also remove things Blueprint manages that aren't in your saved profile (files and folders you track as Resources are never deleted). Compatibility says what Blueprint knows about whether a setting suits this computer's Omarchy: Unknown means it can't confirm, which can leave Restore's permission Reduced; Blocked turns off Apply for the whole run, and Force cannot override it. Press r to plan again after fixing something, d to apply everything else now and leave categories that aren't ready for later, or set a setting's Restore choice to Skip to leave it alone for good.\n\nWill this change my computer or only my saved profile?\nIt changes this computer. Restore can install, replace, or (with Exact) remove settings on this computer. It does not change your saved profile.", "rebuild recreate apply recover exact additive safe force compatibility migration unknown reduced blocked defer deferred replan"},
	{ScreenReconcile, "Sync", SectionWorkflow, "Keep your saved Blueprint setup and this computer in sync. Review changes before anything is saved or applied.", "Sync helps you use the same Blueprint setup across your computers without accidentally overwriting changes.\n\nIt checks the setup saved in Git, compares it with this computer, and shows what is different.\n\nYou decide which changes to keep. Blueprint then asks for approval before saving changes to your profile or applying settings to this computer.\n\nOpening Sync does not install, remove, or change anything on your computer.\n\nWhat does Sync do?\nSync helps keep your Blueprint setup consistent between computers.\n\nIt checks for changes to your shared profile, compares them with this computer, and shows what could be saved or applied.\n\nIf two computers changed the same setting differently, you choose which version to keep.\n\nNothing is applied until you review and approve it.\n\nHow is this different from Capture and Restore?\nCapture saves selected settings from this computer into your Blueprint profile. It does not automatically send those changes to another computer.\n\nRestore applies selected settings from your Blueprint profile to this computer. It does not automatically check for newer changes from other computers.\n\nSync brings these steps together. It checks for newer saved changes, helps you decide what to keep, saves approved changes to the shared profile when needed, and applies approved changes to this computer.\n\nWhat is Profile Git?\nProfile Git manages the saved profile's Git history.\n\nIt lets you inspect, commit, download, and upload changes to the profile files.\n\nSync goes further: it understands individual Blueprint settings and checks them against the computer you are using.\n\nUse Sync for keeping computers consistent. Use Profile Git when you want to inspect or manage the profile's Git history directly.\n\nDoes Sync run automatically?\nNo.\n\nBlueprint checks the shared profile when you open Sync or choose Check for updates.\n\nIt does not continually watch for changes, automatically install software, or silently change your settings.\n\nYou must review and approve a Sync run.\n\nWhat happens when I run Sync?\nBlueprint checks that nothing important has changed since your review.\n\nDepending on what you approved, it may:\n\n1. Save selected changes from this computer into your Blueprint profile.\n2. Update the shared profile in Git so other computers can receive those changes.\n3. Apply selected settings from the profile to this computer.\n4. Check that the changes worked.\n\nBlueprint asks for separate approval before the Capture and Restore steps that need it.\n\nIf an important step fails or something is left unresolved, Sync will not claim that this computer is up to date.\n\nCan Sync remove or overwrite things?\nSometimes, depending on the changes, your settings, and what you approve.\n\nBlueprint shows the proposed actions and their risks before applying them.\n\nA Sync choice does not override your existing Capture or Restore safety settings. Some operations may still be refused.\n\nIf you are unsure what an operation will do, cancel and inspect it first.\n\nWhat happens when I press Check for updates?\nBlueprint checks the configured shared profile for newer changes and refreshes this comparison.\n\nIt does not install software, change your current profile files, or apply settings to this computer.", "sync share other computers shared profile conflict check for updates first-time setup decide"},
	{ScreenPackages, "Packages", SectionSoftware, "See the apps and tools Blueprint remembers for your setup.", "What is this page for?\nPackages shows the apps and tools Blueprint remembers — system packages, AUR packages and global Mise tools — and which of them are different on this computer.\n\nWhat can I do here?\nReview what is saved and what differs. On the Capture and Restore tabs you can choose, for your whole profile or just this computer, which packages Blueprint saves and which it reinstalls, so an app can stay on one computer without being installed everywhere.\n\nWill this change my computer or only my saved profile?\nLooking changes nothing. Changing a Capture or Restore choice only updates your saved profile. Packages are installed or removed on this computer only when you run Restore or Sync.", "software apps aur pacman mise tools install installed"},
	{ScreenThemes, "Themes", SectionSoftware, "See saved themes and which theme this computer is using.", "What is this page for?\nThemes shows the themes saved in your profile and which theme this computer is using.\n\nWhat can I do here?\nReview saved and current themes. Built-in Omarchy themes are saved by name, installed themes keep their source so they can be reinstalled, and your own or modified themes are copied into the profile. A theme that can't be stored in Git (for example an empty theme folder) is not saved, and Capture explains why. On the Capture and Restore tabs you choose which themes Blueprint saves and applies.\n\nWill this change my computer or only my saved profile?\nLooking changes nothing. Capture saves themes into your profile; Restore or Sync installs or switches themes on this computer.", "appearance theme installed"},
	{ScreenPlugins, "Plugins", SectionSoftware, "See the Omarchy plugins Blueprint can save and restore.", "What is this page for?\nPlugins shows the Omarchy plugins saved in your profile and how Blueprint can get each one back.\n\nWhat can I do here?\nReview saved and current plugins. Built-in plugins are saved by name, installed plugins keep their source when possible, and your own or modified plugins are copied. If you also save Shell settings, Shell decides which plugins are turned on; this page is about getting the plugin itself back.\n\nWill this change my computer or only my saved profile?\nLooking changes nothing. Capture saves plugins into your profile; Restore or Sync puts them back on this computer.", "extensions plugin installed"},
	{ScreenDefaults, "Defaults", SectionSoftware, "Review your preferred browser, terminal, editor and other default apps.", "What is this page for?\nDefaults records the apps Omarchy uses as your terminal, browser, editor and agent.\n\nWhat can I do here?\nReview the saved and current defaults. Restore can set supported defaults through Omarchy, but installing the apps themselves belongs to Packages. Your agent choice is remembered and checked, but not changed automatically.\n\nWill this change my computer or only my saved profile?\nLooking changes nothing. Capture saves your defaults into your profile; Restore or Sync can change the default apps on this computer.", "terminal browser editor agent default apps applications"},
	{ScreenConfig, "Config", SectionCustomisation, "Review app settings and configuration files Blueprint can save.", "What is this page for?\nConfig is about your app and system settings files — mainly files under ~/.config, plus supported dotfiles in your home folder — not settings for Blueprint itself.\n\nWhat can I do here?\nBlueprint compares these files with Omarchy's defaults so it saves only real customisations instead of copying everything. State shows what Blueprint found. Policy says whether Blueprint decides automatically, always includes a file, or leaves it out. Some files are looked after by more specific pages and are shown as Handled elsewhere, so they aren't saved twice.\n\nWill this change my computer or only my saved profile?\nLooking changes nothing. Changing Policy only updates your saved profile. Capture saves files into your profile; Restore or Sync can replace files on this computer.", "dotfiles dot files configuration settings .config"},
	{ScreenShell, "Shell", SectionCustomisation, "Review saved Omarchy shell, bar and layout customisations.", "What is this page for?\nShell saves your Omarchy shell, bar and layout customisations, compared with the normal Omarchy setup.\n\nWhat can I do here?\nReview what is saved and what differs. When restoring, Blueprint keeps unrelated changes where it can and reports overlapping changes as conflicts instead of silently replacing them.\n\nWill this change my computer or only my saved profile?\nLooking changes nothing. Capture saves your shell setup into your profile; Restore or Sync can change it on this computer.", "shell bar waybar layout widgets"},
	{ScreenHooks, "Hooks", SectionCustomisation, "See scripts Blueprint remembers for Omarchy events.", "What is this page for?\nHooks are scripts Omarchy runs when certain events happen. This page shows which hook scripts Blueprint has saved and whether this computer has different ones.\n\nWhat can I do here?\nReview saved and current hook scripts. Scripts are saved exactly as written, so keep passwords and other secrets out of them.\n\nWill this change my computer or only my saved profile?\nLooking changes nothing. Capture saves hook scripts into your profile; Restore or Sync can add or replace them on this computer.", "scripts events automation"},
	{ScreenServices, "Services", SectionCustomisation, "Review user services and background tasks Blueprint can manage.", "What is this page for?\nServices shows user services and background tasks Blueprint can manage, and what is saved for them.\n\nWhat can I do here?\nA service Blueprint discovers is not managed until you choose it during Capture. Services that come with packages or apps stay with those packages unless you deliberately choose your own customisation. A service that is merely running is not saved as something to restore.\n\nWill this change my computer or only my saved profile?\nLooking changes nothing. Capture saves your chosen services into your profile; Restore or Sync can set them up or start them on this computer, after asking.", "service timer user unit systemd background automation"},
	{ScreenResources, "Resources", SectionCustomisation, "Manage extra files, folders and projects you want Blueprint to remember.", "What is this page for?\nResources are extra files, folders and Git projects you have asked Blueprint to remember, outside its normal categories.\n\nWhat can I do here?\nAdd or review Resources. Each one can be copied, rebuilt from Git, or rebuilt from Git plus your local changes, and can live in a different place on each computer.\n\nWill this change my computer or only my saved profile?\nAdding or changing a Resource updates your saved profile. Restore or Sync recreates Resources on this computer; Blueprint never deletes a Resource's files.", "files folders directories projects git copy"},
	{ScreenMachines, "Machines", SectionProfile, "Choose settings that can differ between your computers.", "What is this page for?\nMachines lets one computer differ from your shared setup without changing it for your other computers.\n\nWhat can I do here?\nSelect a computer, then set its own Restore defaults (Safe or Force, Additive or Exact), its own choices about which settings to save and apply, and its own locations for Resources that can't use one shared place.\n\nWill this change my computer or only my saved profile?\nOnly your saved profile. These settings take effect the next time you Capture, Restore or Sync on that computer.", "computer laptop desktop host paths mappings"},
	{ScreenSync, "Profile Git", SectionProfile, "Manage the saved profile's Git history and send or receive profile changes manually.", "What is this page for?\nProfile Git manages the Git history of your saved profile — the files that make up your Blueprint profile, not your apps' or Resources' own repositories.\n\nWhat can I do here?\nSee what changed, commit, check the shared repository for updates, download changes (pull) and upload them (push). Blueprint never does this automatically when it starts. Use Git or LazyGit for more advanced repository work. To keep computers consistent setting by setting, use Sync.\n\nWill this change my computer or only my saved profile?\nOnly your saved profile and its Git history. Pulling can update your profile files and pushing sends commits to the shared repository. Profile Git never changes settings on this computer.", "git commit push pull fetch remote profile repository"},
}

func screenInfo(id ScreenID) ScreenInfo {
	for _, info := range screenCatalog {
		if info.ID == id {
			return info
		}
	}
	return ScreenInfo{ID: id}
}

func orderedScreenIDs() []ScreenID {
	ids := make([]ScreenID, len(screenCatalog))
	for i, info := range screenCatalog {
		ids[i] = info.ID
	}
	return ids
}

func sidebarSections() []components.NavSection {
	sections := make([]components.NavSection, 0, 5)
	for _, info := range screenCatalog {
		if len(sections) == 0 || ScreenSection(sections[len(sections)-1].Label) != info.Section {
			sections = append(sections, components.NavSection{Label: string(info.Section)})
		}
		last := len(sections) - 1
		sections[last].Items = append(sections[last].Items, components.NavItem{ID: string(info.ID), Label: info.Label})
	}
	return sections
}

func moveSidebarSection(current ScreenID, delta int) ScreenID {
	sections := sidebarSections()
	for index, section := range sections {
		for _, item := range section.Items {
			if item.ID != string(current) {
				continue
			}
			destination := index + delta
			if destination < 0 || destination >= len(sections) {
				return current
			}
			return ScreenID(sections[destination].Items[0].ID)
		}
	}
	return current
}
